function normalizeUserPreferences(raw={}){
  const p=raw&&typeof raw==='object'?raw:{};
  return {
    conciseMode:p.conciseMode!==false,
    showAdvancedMenu:!!p.showAdvancedMenu,
    startPage:['auto','today','myday','controls','scanner'].includes(p.startPage)?p.startPage:'auto',
    reduceMotion:!!p.reduceMotion,
    largeText:!!p.largeText
  };
}
function applyUserPreferences(){
  state.prefs=normalizeUserPreferences(state.prefs||state.me?.user?.preferences||{});
  document.body.classList.toggle('ui-concise',state.prefs.conciseMode);
  document.body.classList.toggle('ui-reduce-motion',state.prefs.reduceMotion);
  document.body.classList.toggle('ui-large-text',state.prefs.largeText);
  state.allMenu=!!state.prefs.showAdvancedMenu;
  $('#sidebar')?.classList.toggle('all',state.allMenu);
  $('#menuCards')?.classList.toggle('all',state.allMenu);
  if($('#toggleAll'))$('#toggleAll').textContent=state.allMenu?'− Réduire':'＋ Plus de fonctions';
  if($('#menuToggle'))$('#menuToggle').textContent=state.allMenu?'Réduire':'Plus de fonctions';
}
function preferredStartPage(){
  const requested=state.prefs?.startPage||'auto';
  if(requested==='auto')return state.me?.user.role==='employee'?'myday':'today';
  if(requested==='myday'&&state.me?.user.role!=='employee')return 'today';
  return requested;
}
async function saveUserPreferences(patch,{quiet=false}={}){
  const r=await api('/api/account/preferences',{method:'PATCH',body:patch});
  state.prefs=normalizeUserPreferences(r.preferences||{...state.prefs,...patch});
  state.me.user.preferences=state.prefs;
  applyUserPreferences();
  if(!quiet)toast('Paramètres enregistrés');
  return state.prefs;
}

