  const total=Number(plan.progress?.total||plan.steps?.length||0),done=Number(plan.progress?.done||0),pct=Number(plan.progress?.percent||0),active=plan.steps?.find(x=>x.status==='active'),blocked=plan.steps?.filter(x=>x.blocked_at).length||0;
