function tutorialSnoozeKey(){return `hygiesafe:tutorial-snooze:${state.me?.user.id||'user'}:${TUTORIAL_VERSION}`}
async function maybeShowRoleTutorial(){
  if(Number(state.me?.user.tutorialVersion||0)>=TUTORIAL_VERSION||state.tutorialOpen)return;
  const snooze=Number(localStorage.getItem(tutorialSnoozeKey())||0);if(snooze>Date.now())return;
  openTutorialWelcome();
}
function openTutorialWelcome(){
  const role=state.me.user.role,set=tutorialSets[role];
  modal(`Bienvenue ${state.me.user.name.split(/\s+/)[0]||''}`,`<div class="tutorial-welcome"><div class="tutorial-hero-icon">${hsIcon(role==='employee'?'controls':role==='manager'?'team':'home','tutorial-icon')}</div><span class="role-kicker">${roleLabel(role)}</span><h3>Votre prise en main en 2 minutes</h3><p>${set.subtitle}</p><div class="tutorial-welcome-points"><span>✓ ${set.steps.length} étapes courtes</span><span>✓ Adapté à votre rôle</span><span>✓ Rejouable depuis Paramètres</span></div><div class="tutorial-actions"><button class="btn" id="tutorialLater">Plus tard</button><button class="btn primary" id="tutorialStart">Commencer le tutoriel</button></div></div>`);
  $('#tutorialLater').onclick=()=>{localStorage.setItem(tutorialSnoozeKey(),String(Date.now()+24*60*60*1000));closeModal()};
  $('#tutorialStart').onclick=()=>openRoleTutorial(role,{markComplete:true});
}
function openRoleTutorial(role=state.me.user.role,{markComplete=false}={}){
  const set=tutorialSets[role]||tutorialSets.employee;let step=0;state.tutorialOpen=true;
  const render=()=>{const item=set.steps[step],pct=Math.round(((step+1)/set.steps.length)*100);modal(set.title,`<div class="tutorial-progress-row"><span>Étape ${step+1} / ${set.steps.length}</span><b>${pct}%</b></div><div class="progress tutorial-progress"><span style="width:${pct}%"></span></div><div class="tutorial-step"><div class="tutorial-step-icon">${hsIcon(item.icon,'tutorial-icon')}</div><div><h3>${item.title}</h3><p>${item.text}</p></div></div><div class="tutorial-actions"><button class="btn" id="tutorialPrev" ${step===0?'disabled':''}>Précédent</button><button class="btn" id="tutorialOpenPage">Voir l’écran</button><button class="btn primary" id="tutorialNext">${step===set.steps.length-1?'Terminer':'Suivant'}</button></div>`);
    $('#modalClose').onclick=()=>{state.tutorialOpen=false;closeModal()};
    $('#tutorialPrev').onclick=()=>{if(step>0){step--;render()}};
    $('#tutorialOpenPage').onclick=()=>{state.tutorialOpen=false;closeModal();go(item.page)};
    $('#tutorialNext').onclick=async()=>{if(step<set.steps.length-1){step++;render();return}if(markComplete&&role===state.me.user.role){try{const r=await api('/api/account/tutorial',{method:'PATCH',body:{version:TUTORIAL_VERSION}});state.me.user.tutorialVersion=r.tutorialVersion;localStorage.removeItem(tutorialSnoozeKey())}catch(e){console.warn('[tutorial]',e)}}state.tutorialOpen=false;closeModal();toast('Tutoriel terminé. Vous pouvez le relancer depuis Paramètres.');go('today')};
  };render();
}
function helpGuidesForRole(role){
  const shared=[['scanner','scanner','Scanner une DLC','Photo nette → vérifier → enregistrer.'],['controls','controls','Faire un contrôle','Ouvrir À faire → Relever ou Valider.'],['orders','orders','Préparer une commande','Saisir les quantités puis enregistrer.']];
  if(role==='owner')return [['team','team','Ajouter et organiser l’équipe','Inviter les membres et régler les horaires.'],['temperature','equipment','Gérer les équipements','Suivre l’état, les seuils, les pannes et la maintenance.'],['archive','reports','Préparer un contrôle sanitaire','Télécharger les rapports et la sauvegarde.'],...shared];
  if(role==='manager')return [['team','team','Régler les horaires','Définir arrivée et départ des employés.'],['controls','controls','Superviser les contrôles','Voir les actions en attente et terminées.'],['archive','history','Retrouver une action','Consulter l’historique de l’établissement.'],...shared];
  return [['temperature','controls','Faire mon relevé de température','Attendre l’alerte prévue à l’arrivée ou au départ.'],['controls','controls','Voir mes tâches du jour','Tout ce qui est à faire se trouve dans À faire.'],['schedule','timeclock','Pointer mon service','Utiliser la pointeuse si elle est demandée.'],...shared];
}
async function loadHelp(){
  const role=state.me.user.role,set=tutorialSets[role],guides=helpGuidesForRole(role);const canSee=[role,...(role==='owner'?['manager','employee']:role==='manager'?['employee']:[])];
  $('#helpContent').innerHTML=`<div class="help-hero"><div>${hsIcon('profile','help-hero-icon')}<div><span class="role-kicker">Votre rôle : ${roleLabel(role)}</span><h2>${set.title}</h2><p>${set.subtitle}</p></div></div><button class="btn primary" data-self-tutorial>Commencer</button></div><h2 class="help-title">Guides express</h2><div class="help-grid">${guides.map(([icon,page,title,text])=>`<button class="help-card" data-help-go="${page}">${hsIcon(icon,'help-card-icon')}<span><b>${title}</b><small>${text}</small></span><i>→</i></button>`).join('')}</div>${canSee.length>1?`<h2 class="help-title">Tutoriels de l’équipe</h2><p class="muted help-intro">Pratique pour comprendre ce que voit chaque profil.</p><div class="tutorial-role-grid">${canSee.map(r=>`<button class="tutorial-role-card ${r===role?'current':''}" data-tutorial-role="${r}">${hsIcon(r==='owner'?'home':r==='manager'?'team':'controls','tutorial-role-icon')}<b>${roleLabel(r)}</b><small>${tutorialSets[r].steps.length} étapes</small></button>`).join('')}</div>`:''}<div class="help-foot"><b>Besoin d’un rappel ?</b><span>Le bouton Aide reste disponible en haut de l’application.</span></div>`;
  $$('[data-help-go]').forEach(b=>b.onclick=()=>go(b.dataset.helpGo));$$('[data-self-tutorial]').forEach(b=>b.onclick=()=>openRoleTutorial(role,{markComplete:true}));$$('[data-tutorial-role]').forEach(b=>b.onclick=()=>openRoleTutorial(b.dataset.tutorialRole,{markComplete:b.dataset.tutorialRole===role}));
  $('#replayMyTutorial').onclick=()=>openRoleTutorial(role,{markComplete:true});
}

function openInvite(){modal('Inviter un membre',`<form id="inviteForm"><div class="field"><label>Nom</label><input name="name" required></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Rôle</label><select name="role"><option value="employee">Employé</option><option value="manager">Responsable</option></select></div><button class="btn primary">Créer l’invitation</button></form><div id="inviteResult"></div>`);$('#inviteForm').onsubmit=async e=>{e.preventDefault();const d=formDataObj(e.currentTarget),r=await api('/api/auth/team/invite',{method:'POST',body:d});$('#inviteResult').innerHTML=`<div class="notice good" style="margin-top:14px"><b>Invitation créée.</b><br>Un e-mail est envoyé via Resend lorsqu’il est configuré.</div><img src="${r.qr}" alt="QR invitation" style="width:180px;display:block;margin:14px auto"><div class="field"><input value="${esc(r.inviteUrl)}" readonly></div>`}}
function openPassword(){modal('Changer le mot de passe',`<form id="pwdForm"><div class="field"><label>Mot de passe actuel</label><input name="currentPassword" type="password" required></div><div class="field"><label>Nouveau mot de passe</label><input name="newPassword" type="password" minlength="12" required></div><button class="btn primary">Modifier</button></form>`);$('#pwdForm').onsubmit=async e=>{e.preventDefault();await api('/api/account/change-password',{method:'POST',body:formDataObj(e.currentTarget)});closeModal();toast('Mot de passe modifié')}}
function openDeleteOrg(){modal('Supprimer mon entreprise',`<div class="admin-note">Cette action supprime les utilisateurs, contrôles, photos, documents et historiques de l’entreprise.</div><form id="deleteForm"><div class="field"><label>Mot de passe</label><input name="password" type="password" required></div><div class="field"><label>Écrivez SUPPRIMER</label><input name="confirmation" required></div><button class="btn danger">Supprimer définitivement</button></form>`);$('#deleteForm').onsubmit=async e=>{e.preventDefault();const d=formDataObj(e.currentTarget);if(d.confirmation!=='SUPPRIMER')return toast('Confirmation incorrecte.',true);await api('/api/account/delete-organization',{method:'POST',body:d});location.href='/'}}

async function onboarding(){let cfg=await api('/api/onboarding');let step=Math.max(1,Number(cfg.onboarding_step||1));async function render(){const pct=step*20;let html=`<div class="progress"><span style="width:${pct}%"></span></div>`;if(step===1)html+=`<span class="role-kicker">Configuration gérant</span><h3>1. Votre établissement</h3><p class="muted">Quelques informations suffisent pour préparer votre espace.</p><form id="obForm"><div class="field"><label>Nom</label><input name="name" value="${esc(cfg.name||state.me.organization.name)}" required></div><div class="field"><label>Activité</label><select name="businessType"><option value="restaurant">Restaurant</option><option value="snack">Snack</option><option value="boulangerie">Boulangerie</option><option value="pizzeria">Pizzeria</option><option value="autre">Autre</option></select></div><button class="btn primary">Continuer</button></form>`;
 else if(step===2)html+=`<h3>2. Vos équipements</h3><p class="muted">Indiquez seulement les appareils réellement présents. Vous pourrez les renommer ensuite.</p><form id="obForm"><div class="form-grid">${[['fridges','Frigos',1],['freezers','Congélateurs',1],['coldRoomsPositive','Chambres froides +',0],['coldRoomsNegative','Chambres froides -',0],['displayFridges','Vitrines froides',0],['fryers','Friteuses',0]].map(([n,l,v])=>`<div class="field"><label>${l}</label><input name="${n}" type="number" min="0" max="30" value="${cfg.equipment?.[n]??v}"></div>`).join('')}</div><button class="btn primary">Continuer</button></form>`;
 else if(step===3)html+=`<h3>3. Contrôles de base</h3><p class="muted">Choisissez les contrôles utiles. Les horaires employés pourront ensuite déclencher leurs relevés au début et à la fin du service.</p><form id="obForm"><div class="field"><label>Relevés de température / jour</label><select name="temperaturePerDay"><option value="1">1</option><option value="2" selected>2</option><option value="3">3</option></select></div>${[['cleaning','Nettoyage quotidien'],['dlc','Contrôle DLC / DDM'],['handwash','Lave-mains'],['oil','Huiles de friture']].map(([n,l])=>`<label style="display:flex;gap:8px;margin:12px 0"><input type="checkbox" name="${n}" checked> ${l}</label>`).join('')}<div class="field"><label>Fin de service</label><input type="time" name="closingTime" value="22:00"></div><button class="btn primary">Continuer</button></form>`;
 else if(step===4)html+=`<h3>4. Votre équipe</h3><p class="muted">Facultatif. Un Responsable supervise le terrain ; un Employé réalise les actions qui lui sont présentées. Chacun possède son accès personnel.</p><form id="obForm"><div class="field"><label>Nom d’un employé</label><input name="employeeName"></div><div class="field"><label>E-mail</label><input name="employeeEmail" type="email"></div><div class="field"><label>Rôle</label><select name="employeeRole"><option value="employee">Employé</option><option value="manager">Responsable</option></select></div><button class="btn primary">Continuer</button><button type="button" class="btn" id="skipTeam">Passer</button></form>`;
 else html+=`<h3>5. Votre espace est prêt</h3><p>HygieSafe va créer la base de votre établissement. Ensuite, un tutoriel Gérant vous montrera les écrans importants.</p><div class="notice good">Votre essai de 14 jours est déjà actif.</div><button class="btn primary" id="finishOb">Ouvrir HygieSafe</button>`;
 modal('Configuration HygieSafe',html,{locked:true});if(step<5){$('#obForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);let body;if(step===1)body={name:f.get('name'),businessType:f.get('businessType')};if(step===2)body=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)]));if(step===3)body={temperaturePerDay:Number(f.get('temperaturePerDay')),cleaning:f.has('cleaning'),dlc:f.has('dlc'),handwash:f.has('handwash'),oil:f.has('oil'),closingTime:f.get('closingTime')};if(step===4){if(f.get('employeeName')&&f.get('employeeEmail'))await api('/api/auth/team/invite',{method:'POST',body:{name:f.get('employeeName'),email:f.get('employeeEmail'),role:f.get('employeeRole')}});body={}}await api(`/api/onboarding/step/${step}`,{method:'PUT',body});step++;await render()};if(step===4)$('#skipTeam').onclick=async()=>{await api('/api/onboarding/step/4',{method:'PUT',body:{}});step=5;render()}}else $('#finishOb').onclick=async()=>{await api('/api/onboarding/step/5',{method:'PUT',body:{}});state.me=await api('/api/auth/me');setCsrf(state.me.csrf);closeModal();toast('Votre espace est prêt');go('today');setTimeout(()=>openRoleTutorial('owner',{markComplete:true}),350)}}await render()}
init().catch(handleError);
